set-payload.value:
#[output application/json --- {n: sizeOf(payload), entries: (payload pluck ((v, k) -> {
  key: k as String replace /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/ with "<uuid>",
  "type": typeOf(v) as String,
  cls: v.^class,
  json: write(if ((v.^class default "") endsWith "TaskRepositoryItem") {
      historyLength: v.historyLength,
      streamingContext: if (v.streamingContext == null) null else {
        bufferedEvents: v.streamingContext.bufferedEvents map {eventId: $.eventId, eventType: $.eventType, eventData: $.eventData},
        workerInstanceId: v.streamingContext.workerInstanceId,
        requestId: v.streamingContext.requestId
      },
      contextId: v.contextId,
      history: v.history,
      taskState: v.taskState,
      task: v.task,
      pushNotificationConfigs: v.pushNotificationConfigs map {proxyConfig: $.proxyConfig, timeout: $.timeout, url: $.url, token: $.token, additionalHeaders: $.additionalHeaders, id: $.id, authentication: $.authentication}
    } else {contextId: v.contextId}, "application/json")
    replace /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/ with "<uuid>"
    replace /"workerInstanceId": "[^"]*"/ with "\"workerInstanceId\": \"<worker>\""
    replace /20[0-9]{2}-[0-9]{2}-[0-9]{2}T[0-9:.]+Z/ with "<ts>"
}) orderBy $.cls)}]
